const mongoose = require("mongoose");

// Stores the most recent replenishment recommendation per product.
// Regenerated by services/replenishmentService.js (on demand or via /generate).
const recommendationSchema = new mongoose.Schema(
  {
    product: { type: mongoose.Schema.Types.ObjectId, ref: "Product", required: true, unique: true },
    currentStock: { type: Number, required: true },
    averageDailyDemand: { type: Number, required: true },
    forecastDailyDemand: { type: Number, required: true }, // 7-day moving average
    leadTimeDays: { type: Number, required: true },
    safetyStock: { type: Number, required: true },
    reorderPoint: { type: Number, required: true },
    recommendedQuantity: { type: Number, required: true },
    shouldReorder: { type: Boolean, required: true },
    priority: { type: String, enum: ["LOW", "MEDIUM", "HIGH", "CRITICAL"], required: true },
    reason: { type: String, required: true },
    generatedAt: { type: Date, default: Date.now },
  },
  { timestamps: true }
);

module.exports = mongoose.model("Recommendation", recommendationSchema);
